-- Initial Porquinho schema, based on the schema approved on 2026-11-09.
-- Domain IDs are generated by clients so offline records retain stable IDs.
-- Client roles receive read access only; transactional write RPCs are delivered separately.

CREATE TABLE public.user_preferences (
    owner_id UUID PRIMARY KEY REFERENCES auth.users (id) ON DELETE RESTRICT,
    theme TEXT CHECK (theme IN ('light', 'dark')),
    time_zone_id TEXT NOT NULL DEFAULT 'America/Sao_Paulo',
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE public.period_configurations (
    owner_id UUID NOT NULL REFERENCES auth.users (id) ON DELETE RESTRICT,
    id UUID NOT NULL,
    mode TEXT NOT NULL CHECK (mode IN ('calendar_month', 'custom_cycle')),
    custom_start_day SMALLINT,
    effective_from DATE NOT NULL,
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, id),
    UNIQUE (owner_id, effective_from),
    CHECK (
        (mode = 'calendar_month' AND custom_start_day IS NULL)
        OR (mode = 'custom_cycle'
            AND custom_start_day IS NOT NULL
            AND custom_start_day BETWEEN 1 AND 31)
    )
);

CREATE TABLE public.accounting_periods (
    owner_id UUID NOT NULL REFERENCES auth.users (id) ON DELETE RESTRICT,
    id UUID NOT NULL,
    configuration_id UUID NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, id),
    UNIQUE (owner_id, start_date),
    FOREIGN KEY (owner_id, configuration_id)
        REFERENCES public.period_configurations (owner_id, id) ON DELETE RESTRICT,
    CHECK (start_date < end_date)
);

CREATE INDEX accounting_periods_owner_end_date_idx
    ON public.accounting_periods (owner_id, end_date);

CREATE TABLE public.categories (
    owner_id UUID NOT NULL REFERENCES auth.users (id) ON DELETE RESTRICT,
    id UUID NOT NULL,
    kind TEXT NOT NULL CHECK (kind IN ('income', 'expense')),
    name TEXT NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, id)
);

CREATE FUNCTION public.prevent_category_kind_change()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $function$
BEGIN
    IF NEW.kind IS DISTINCT FROM OLD.kind THEN
        RAISE EXCEPTION 'category kind is immutable'
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.prevent_category_kind_change() FROM PUBLIC;

CREATE TRIGGER categories_kind_immutable
    BEFORE UPDATE OF kind ON public.categories
    FOR EACH ROW
    EXECUTE FUNCTION public.prevent_category_kind_change();

CREATE TABLE public.subcategories (
    owner_id UUID NOT NULL REFERENCES auth.users (id) ON DELETE RESTRICT,
    id UUID NOT NULL,
    category_id UUID NOT NULL,
    name TEXT NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, id),
    UNIQUE (owner_id, category_id, id),
    FOREIGN KEY (owner_id, category_id)
        REFERENCES public.categories (owner_id, id) ON DELETE RESTRICT
);

CREATE FUNCTION public.validate_category_assignment()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $function$
DECLARE
    category_kind TEXT;
BEGIN
    IF NEW.subcategory_id IS NOT NULL AND NEW.category_id IS NULL THEN
        RAISE EXCEPTION 'subcategory requires a category'
            USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.category_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT category.kind
    INTO category_kind
    FROM public.categories AS category
    WHERE category.owner_id = NEW.owner_id
      AND category.id = NEW.category_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'category does not belong to this owner'
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    IF category_kind <> TG_ARGV[0] THEN
        RAISE EXCEPTION 'category kind does not match the record kind'
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.validate_category_assignment() FROM PUBLIC;

CREATE TABLE public.income_recurrence_templates (
    owner_id UUID NOT NULL REFERENCES auth.users (id) ON DELETE RESTRICT,
    id UUID NOT NULL,
    description TEXT,
    frequency TEXT NOT NULL CHECK (frequency IN ('monthly', 'by_period')),
    starts_on DATE NOT NULL,
    monthly_reference_day SMALLINT,
    value_mode TEXT NOT NULL CHECK (value_mode IN ('fixed', 'variable')),
    default_amount_centavos BIGINT CHECK (default_amount_centavos >= 0),
    category_id UUID,
    subcategory_id UUID,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, id),
    FOREIGN KEY (owner_id, category_id)
        REFERENCES public.categories (owner_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (owner_id, category_id, subcategory_id)
        REFERENCES public.subcategories (owner_id, category_id, id) ON DELETE RESTRICT,
    CHECK (subcategory_id IS NULL OR category_id IS NOT NULL),
    CHECK (
        (frequency = 'monthly'
            AND monthly_reference_day IS NOT NULL
            AND monthly_reference_day BETWEEN 1 AND 31)
        OR (frequency = 'by_period' AND monthly_reference_day IS NULL)
    ),
    CHECK (
        (value_mode = 'fixed' AND default_amount_centavos IS NOT NULL)
        OR (value_mode = 'variable' AND default_amount_centavos IS NULL)
    )
);

CREATE TABLE public.expense_recurrence_templates (
    owner_id UUID NOT NULL REFERENCES auth.users (id) ON DELETE RESTRICT,
    id UUID NOT NULL,
    description TEXT,
    frequency TEXT NOT NULL CHECK (frequency IN ('monthly', 'by_period')),
    starts_on DATE NOT NULL,
    monthly_reference_day SMALLINT,
    value_mode TEXT NOT NULL CHECK (value_mode IN ('fixed', 'variable')),
    default_amount_centavos BIGINT CHECK (default_amount_centavos >= 0),
    category_id UUID,
    subcategory_id UUID,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, id),
    FOREIGN KEY (owner_id, category_id)
        REFERENCES public.categories (owner_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (owner_id, category_id, subcategory_id)
        REFERENCES public.subcategories (owner_id, category_id, id) ON DELETE RESTRICT,
    CHECK (subcategory_id IS NULL OR category_id IS NOT NULL),
    CHECK (
        (frequency = 'monthly'
            AND monthly_reference_day IS NOT NULL
            AND monthly_reference_day BETWEEN 1 AND 31)
        OR (frequency = 'by_period' AND monthly_reference_day IS NULL)
    ),
    CHECK (
        (value_mode = 'fixed' AND default_amount_centavos IS NOT NULL)
        OR (value_mode = 'variable' AND default_amount_centavos IS NULL)
    )
);

CREATE TABLE public.income_entries (
    owner_id UUID NOT NULL REFERENCES auth.users (id) ON DELETE RESTRICT,
    id UUID NOT NULL,
    description TEXT,
    amount_centavos BIGINT CHECK (amount_centavos >= 0),
    status TEXT NOT NULL CHECK (status IN ('pending', 'received', 'cancelled')),
    received_on DATE,
    category_id UUID,
    subcategory_id UUID,
    accounting_period_id UUID,
    recurrence_template_id UUID,
    scheduled_for_date DATE,
    scheduled_period_id UUID,
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, id),
    FOREIGN KEY (owner_id, category_id)
        REFERENCES public.categories (owner_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (owner_id, category_id, subcategory_id)
        REFERENCES public.subcategories (owner_id, category_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (owner_id, accounting_period_id)
        REFERENCES public.accounting_periods (owner_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (owner_id, recurrence_template_id)
        REFERENCES public.income_recurrence_templates (owner_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (owner_id, scheduled_period_id)
        REFERENCES public.accounting_periods (owner_id, id) ON DELETE RESTRICT,
    CHECK (subcategory_id IS NULL OR category_id IS NOT NULL),
    CHECK (amount_centavos IS NOT NULL OR recurrence_template_id IS NOT NULL),
    CHECK (
        (recurrence_template_id IS NULL
            AND scheduled_for_date IS NULL
            AND scheduled_period_id IS NULL)
        OR (recurrence_template_id IS NOT NULL AND scheduled_for_date IS NOT NULL)
    ),
    CHECK (
        (status = 'pending'
            AND recurrence_template_id IS NOT NULL
            AND received_on IS NULL
            AND accounting_period_id IS NULL)
        OR (status = 'received'
            AND amount_centavos IS NOT NULL
            AND received_on IS NOT NULL
            AND accounting_period_id IS NOT NULL)
        OR (status = 'cancelled'
            AND ((received_on IS NULL AND accounting_period_id IS NULL)
                OR (amount_centavos IS NOT NULL
                    AND received_on IS NOT NULL
                    AND accounting_period_id IS NOT NULL)))
    )
);

CREATE TRIGGER income_templates_category_assignment
    BEFORE INSERT OR UPDATE OF category_id, subcategory_id ON public.income_recurrence_templates
    FOR EACH ROW
    EXECUTE FUNCTION public.validate_category_assignment('income');

CREATE TRIGGER expense_templates_category_assignment
    BEFORE INSERT OR UPDATE OF category_id, subcategory_id ON public.expense_recurrence_templates
    FOR EACH ROW
    EXECUTE FUNCTION public.validate_category_assignment('expense');

CREATE TRIGGER income_entries_category_assignment
    BEFORE INSERT OR UPDATE OF category_id, subcategory_id ON public.income_entries
    FOR EACH ROW
    EXECUTE FUNCTION public.validate_category_assignment('income');

CREATE UNIQUE INDEX income_entries_recurrence_occurrence_uidx
    ON public.income_entries (owner_id, recurrence_template_id, scheduled_for_date)
    WHERE recurrence_template_id IS NOT NULL;
CREATE INDEX income_entries_period_date_idx
    ON public.income_entries (owner_id, accounting_period_id, received_on);
CREATE INDEX income_entries_category_date_idx
    ON public.income_entries (owner_id, category_id, received_on);

CREATE TABLE public.expense_entries (
    owner_id UUID NOT NULL REFERENCES auth.users (id) ON DELETE RESTRICT,
    id UUID NOT NULL,
    description TEXT,
    amount_centavos BIGINT CHECK (amount_centavos >= 0),
    competence_on DATE NOT NULL,
    due_on DATE,
    paid_on DATE,
    status TEXT NOT NULL CHECK (status IN ('pending', 'paid', 'cancelled')),
    category_id UUID,
    subcategory_id UUID,
    accounting_period_id UUID NOT NULL,
    recurrence_template_id UUID,
    scheduled_for_date DATE,
    scheduled_period_id UUID,
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, id),
    FOREIGN KEY (owner_id, category_id)
        REFERENCES public.categories (owner_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (owner_id, category_id, subcategory_id)
        REFERENCES public.subcategories (owner_id, category_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (owner_id, accounting_period_id)
        REFERENCES public.accounting_periods (owner_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (owner_id, recurrence_template_id)
        REFERENCES public.expense_recurrence_templates (owner_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (owner_id, scheduled_period_id)
        REFERENCES public.accounting_periods (owner_id, id) ON DELETE RESTRICT,
    CHECK (subcategory_id IS NULL OR category_id IS NOT NULL),
    CHECK (amount_centavos IS NOT NULL OR recurrence_template_id IS NOT NULL),
    CHECK (
        (recurrence_template_id IS NULL
            AND scheduled_for_date IS NULL
            AND scheduled_period_id IS NULL)
        OR (recurrence_template_id IS NOT NULL AND scheduled_for_date IS NOT NULL)
    ),
    CHECK (
        (status = 'pending' AND paid_on IS NULL)
        OR (status = 'paid' AND amount_centavos IS NOT NULL AND paid_on IS NOT NULL)
        OR (status = 'cancelled' AND (paid_on IS NULL OR amount_centavos IS NOT NULL))
    )
);

CREATE TRIGGER expense_entries_category_assignment
    BEFORE INSERT OR UPDATE OF category_id, subcategory_id ON public.expense_entries
    FOR EACH ROW
    EXECUTE FUNCTION public.validate_category_assignment('expense');

CREATE UNIQUE INDEX expense_entries_recurrence_occurrence_uidx
    ON public.expense_entries (owner_id, recurrence_template_id, scheduled_for_date)
    WHERE recurrence_template_id IS NOT NULL;
CREATE INDEX expense_entries_period_date_idx
    ON public.expense_entries (owner_id, accounting_period_id, competence_on);
CREATE INDEX expense_entries_category_date_idx
    ON public.expense_entries (owner_id, category_id, competence_on);
CREATE INDEX expense_entries_due_pending_idx
    ON public.expense_entries (owner_id, due_on)
    WHERE status = 'pending' AND due_on IS NOT NULL;

CREATE TABLE public.investment_allocations (
    owner_id UUID NOT NULL REFERENCES auth.users (id) ON DELETE RESTRICT,
    id UUID NOT NULL,
    amount_centavos BIGINT NOT NULL CHECK (amount_centavos >= 0),
    allocated_on DATE NOT NULL,
    accounting_period_id UUID NOT NULL,
    cancelled_at TIMESTAMPTZ,
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, id),
    FOREIGN KEY (owner_id, accounting_period_id)
        REFERENCES public.accounting_periods (owner_id, id) ON DELETE RESTRICT
);

CREATE INDEX investment_allocations_period_date_idx
    ON public.investment_allocations (owner_id, accounting_period_id, allocated_on)
    WHERE cancelled_at IS NULL;

CREATE TABLE public.audit_events (
    owner_id UUID NOT NULL REFERENCES auth.users (id) ON DELETE RESTRICT,
    id UUID NOT NULL,
    entity_type TEXT NOT NULL,
    entity_id UUID NOT NULL,
    operation TEXT NOT NULL,
    actor_id UUID NOT NULL REFERENCES auth.users (id) ON DELETE RESTRICT,
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    previous_values JSONB,
    new_values JSONB,
    operation_id UUID,
    PRIMARY KEY (owner_id, id),
    CHECK (actor_id = owner_id)
);

CREATE INDEX audit_events_entity_time_idx
    ON public.audit_events (owner_id, entity_type, entity_id, occurred_at);

CREATE TABLE public.applied_sync_operations (
    owner_id UUID NOT NULL REFERENCES auth.users (id) ON DELETE RESTRICT,
    idempotency_key UUID NOT NULL,
    content_hash BYTEA NOT NULL,
    result_payload JSONB NOT NULL,
    applied_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, idempotency_key)
);

CREATE TABLE public.sync_conflicts (
    owner_id UUID NOT NULL REFERENCES auth.users (id) ON DELETE RESTRICT,
    id UUID NOT NULL,
    entity_type TEXT NOT NULL,
    entity_id UUID NOT NULL,
    base_version BIGINT NOT NULL CHECK (base_version >= 0),
    remote_version BIGINT NOT NULL CHECK (remote_version > 0),
    local_snapshot JSONB NOT NULL,
    remote_snapshot JSONB NOT NULL,
    status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved')),
    resolution_payload JSONB,
    resolved_at TIMESTAMPTZ,
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, id),
    CHECK (
        (status = 'open' AND resolution_payload IS NULL AND resolved_at IS NULL)
        OR (status = 'resolved' AND resolution_payload IS NOT NULL AND resolved_at IS NOT NULL)
    )
);

CREATE INDEX sync_conflicts_open_idx
    ON public.sync_conflicts (owner_id, created_at)
    WHERE status = 'open';

-- Revoke writes explicitly; RLS policies do not replace SQL grants.
REVOKE CREATE ON SCHEMA public FROM PUBLIC, anon, authenticated;
GRANT USAGE ON SCHEMA public TO authenticated;
REVOKE ALL PRIVILEGES ON TABLE
    public.user_preferences,
    public.period_configurations,
    public.accounting_periods,
    public.categories,
    public.subcategories,
    public.income_recurrence_templates,
    public.expense_recurrence_templates,
    public.income_entries,
    public.expense_entries,
    public.investment_allocations,
    public.audit_events,
    public.applied_sync_operations,
    public.sync_conflicts
FROM PUBLIC, anon, authenticated;

GRANT SELECT ON TABLE
    public.user_preferences,
    public.period_configurations,
    public.accounting_periods,
    public.categories,
    public.subcategories,
    public.income_recurrence_templates,
    public.expense_recurrence_templates,
    public.income_entries,
    public.expense_entries,
    public.investment_allocations,
    public.audit_events,
    public.applied_sync_operations,
    public.sync_conflicts
TO authenticated;

DO $block$
DECLARE
    table_name TEXT;
BEGIN
    FOREACH table_name IN ARRAY ARRAY[
        'user_preferences',
        'period_configurations',
        'accounting_periods',
        'categories',
        'subcategories',
        'income_recurrence_templates',
        'expense_recurrence_templates',
        'income_entries',
        'expense_entries',
        'investment_allocations',
        'audit_events',
        'applied_sync_operations',
        'sync_conflicts'
    ]
    LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', table_name);
        EXECUTE format(
            'CREATE POLICY porquinho_read_own ON public.%I FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL AND owner_id = auth.uid())',
            table_name
        );
    END LOOP;
END;
$block$;
